def f_D(x, y):
    return (x + y) * (x + y + 1) // 2 + x

parity_matrix = []
for y in range(4):
    row = []
    for x in range(4):
        value = f_D(x, y)
        row.append(value % 2)
    parity_matrix.append(row)

print("Parity Matrix (y rows, x columns):")
for row in parity_matrix:
    print(row)

